import csv

def count_large_orders(path, threshold=60):
    count = 0
    with open(path, newline="") as handle:
        for row in csv.DictReader(handle):
            if int(row["amount"]) > threshold:
                count += 1
    return count

print(count_large_orders("orders.csv"))

