import logging
logger = logging.getLogger("orders")

def safe_divide(total, count):
    try:
        return total / count
    except ZeroDivisionError:
        logger.warning("count was 0; returning 0 instead of dividing")
        return 0

print(safe_divide(150, 3))
print(safe_divide(150, 0))

orders = [
    {"order_id": 1, "country": "IN", "amount": 100},
    {"order_id": 1, "country": "IN", "amount": 100},
    {"order_id": 2, "country": "US", "amount": 50},
    {"order_id": 3, "country": "IN", "amount": 20},
    {"order_id": 4, "country": None, "amount": 10},
    {"order_id": 5, "country": "US", "amount": -5},
]

seen = set()
unique = []
for order in orders:
    key = tuple(sorted(order.items()))
    if key not in seen:
        seen.add(key)
        unique.append(order)

totals = {}
for order in unique:
    if order["country"] and order["amount"] > 0:
        totals[order["country"]] = totals.get(order["country"], 0) + order["amount"]

for country in sorted(totals):
    print(country, totals[country])

